function buildDockerfile(opts: { javaVersion: number; jarName: string; port: number }): string {
  return [
    `FROM eclipse-temurin:${opts.javaVersion}-jdk AS build`,
    "WORKDIR /app",
    "COPY . .",
    "RUN ./mvnw -q package -DskipTests",
    `FROM eclipse-temurin:${opts.javaVersion}-jre`,
    "WORKDIR /app",
    `COPY --from=build /app/target/${opts.jarName} app.jar`,
    "RUN useradd --system appuser",
    "USER appuser",
    `EXPOSE ${opts.port}`,
    'ENTRYPOINT ["java", "-jar", "app.jar"]'
  ].join("\n");
}

function dockerRun(opts: { image: string; name: string; ports?: [number, number][]; env?: Record<string, string>; detach?: boolean }): string {
  const parts = ["docker run"];

  if (opts.detach) {
    parts.push("-d");
  }

  parts.push("--name", opts.name);

  for (const [host, container] of opts.ports ?? []) {
    parts.push("-p", `${host}:${container}`);
  }

  for (const [key, value] of Object.entries(opts.env ?? {})) {
    parts.push("-e", `${key}=${value}`);
  }

  parts.push(opts.image);
  return parts.join(" ");
}

