const result = buildDockerfile({ javaVersion: 21, jarName: "task-api.jar", port: 8080 });
const lines = result.split("\n");
const required = [
  "FROM eclipse-temurin:21-jdk AS build",
  "WORKDIR /app",
  "COPY . .",
  "RUN ./mvnw -q package -DskipTests",
  "FROM eclipse-temurin:21-jre",
  "WORKDIR /app",
  "COPY --from=build /app/target/task-api.jar app.jar",
  "RUN useradd --system appuser",
  "USER appuser",
  "EXPOSE 8080",
  'ENTRYPOINT ["java", "-jar", "app.jar"]'
];
let previous = -1;
for (const line of required) {
  const index = lines.indexOf(line, previous + 1);
  if (index === -1 || index <= previous) return false;
  previous = index;
}
return true;

const result = buildDockerfile({ javaVersion: 17, jarName: "app.jar", port: 8081 });
const lines = result.split("\n");
return lines.includes("FROM eclipse-temurin:17-jdk AS build") && lines.includes("FROM eclipse-temurin:17-jre");

const result = buildDockerfile({ javaVersion: 21, jarName: "app.jar", port: 8080 });
const lines = result.split("\n");
const useradd = lines.indexOf("RUN useradd --system appuser");
const user = lines.indexOf("USER appuser");
return useradd !== -1 && user !== -1 && user > useradd;

const result = dockerRun({
  image: "task-api:2.0",
  name: "backend",
  ports: [[8080, 8080], [8443, 8443]],
  env: { SPRING_PROFILES_ACTIVE: "prod", APP_MODE: "safe" },
  detach: true
});
return result === "docker run -d --name backend -p 8080:8080 -p 8443:8443 -e SPRING_PROFILES_ACTIVE=prod -e APP_MODE=safe task-api:2.0";
